import { readPurchaseQuote } from '../app/lootbox.js';
import { get, getActingAddress, subscribe } from '../app/store.js';
import { displayEthCompact } from '../app/scaling.js';
import { registerComponentPoll } from '../app/component-poll.js';
import { TX_CONFIRMED_EVENT } from '../app/contracts.js';
import { setActionFeedback } from './action-feedback.js';

class TicketQuickBuy extends HTMLElement {
  #unsubs = [];
  #quote = null;
  #busy = false;
  #request = 0;
  #refresh = async () => {
    const request = ++this.#request;
    const quote = await readPurchaseQuote({ fresh: true });
    if (!this.isConnected || request !== this.#request) return;
    this.#quote = quote;
    this.#paint();
  };

  connectedCallback() {
    if (this.#unsubs.length) return;
    this.innerHTML = '<button type="button" class="site-ticket-buy" disabled>BUY ONE – — ETH</button><span role="status" hidden></span>';
    const button = this.querySelector('button');
    button.addEventListener('click', async event => {
      event.stopPropagation();
      if (button.disabled || this.#busy) return;
      const player = getActingAddress();
      const priceWei = this.#quote?.priceWei;
      this.#busy = true;
      this.#paint();
      const feedback = this.querySelector('[role="status"]');
      setActionFeedback(feedback, '');
      try {
        await import('/app/components/app-decimator-panel.js');
        if (!this.isConnected || getActingAddress() !== player) {
          throw new Error('The selected account changed. Check the account and try again.');
        }
        const panel = document.querySelector('app-decimator-panel');
        if (!panel?.quickBuyOneTicket) throw new Error('Ticket purchases are still loading. Try again.');
        const result = await panel.quickBuyOneTicket({ player, priceWei });
        setActionFeedback(feedback, result.message);
      } catch (error) {
        setActionFeedback(feedback, error?.message || 'Ticket purchase was not completed.');
      } finally {
        this.#busy = false;
        if (this.isConnected) {
          this.#paint();
          void this.#refresh();
        }
      }
    });
    for (const key of ['connected.address', 'viewing.address', 'ui.mode', 'ui.chainOk']) {
      this.#unsubs.push(subscribe(key, () => this.#paint()));
    }
    this.#unsubs.push(registerComponentPoll(this.#refresh, 30_000, { owner: this }));
    document.addEventListener(TX_CONFIRMED_EVENT, this.#refresh);
    this.#unsubs.push(() => document.removeEventListener(TX_CONFIRMED_EVENT, this.#refresh));
    this.#paint();
    void this.#refresh();
  }

  disconnectedCallback() {
    ++this.#request;
    for (const unsubscribe of this.#unsubs.splice(0)) unsubscribe();
  }

  #paint() {
    const button = this.querySelector('button');
    if (!button) return;
    const price = this.#quote?.priceWei;
    const label = this.#busy ? 'BUYING…' : `BUY ONE – ${price ? displayEthCompact(price, 9) : '—'} ETH`;
    if (button.textContent !== label) button.textContent = label;
    button.disabled = this.#busy || !price || !getActingAddress() || get('ui.chainOk') === false;
    button.setAttribute('aria-busy', String(this.#busy));
    button.title = !getActingAddress() ? 'Connect your wallet and select an account to buy'
      : !price ? 'Loading the current ticket price'
        : `Buy exactly one ticket for ${displayEthCompact(price, 9)} ETH`;
  }
}

if (!customElements.get('ticket-quick-buy')) customElements.define('ticket-quick-buy', TicketQuickBuy);

export function mountTicketQuickBuy(ticket) {
  const quadrant = ticket?.closest('.replay-tq');
  if (!quadrant || quadrant.querySelector('ticket-quick-buy')) return;
  quadrant.append(document.createElement('ticket-quick-buy'));
}
